insert into public.email_automations(id,key,name,trigger_type,is_active) values('16094c0f-ae0c-585d-8bbd-6ce49bb2174c','course_month-male-female','Месяц М+Ж','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('month-male-female','Месяц М+Ж','practicum','',90,3,5,'16094c0f-ae0c-585d-8bbd-6ce49bb2174c','aa85ce1afeb367f95e0670e7bdd2bcfecc8fe91135846f02ff2e9f0847b9324b') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('d5b816e9-ee23-5564-89d1-b402e0e42054','16094c0f-ae0c-585d-8bbd-6ce49bb2174c','Урок 1',1,0,'{М+Ж} Добро пожаловать!','{"ru":"{М+Ж} Добро пожаловать!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png" alt="Месяц М+Ж" width="504" height="195" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я очень рад, что вы решились в течение месяца целенаправленно поработать с темой мужско-женских отношений. Сразу хочу обратить ваше внимание на то, что эта тема значительно шире ваших отношений с противоположным полом. Ведь мужское и женское окружает вас повсюду - и в мире природы, и в вашем внутреннем мире, и даже в языке, на котором мы говорим... Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые мы будем выполнять на совместных практиках, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу через Zoom тонко проконтролировать состояние каждого. А люди бывают разные. У каждого есть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие изменений<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь любовью... Так что поток уже поставлен. Входите в него и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для гармонизации мужско-женских отношений.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. Он поможет вам глубже разобраться в том, что такое любовь между мужчиной и женщиной, и что именно вы можете гармонизировать в течение этого месяца. Очень важно почувствовать её энергию, а также сформулировать лично для себя намерение на этот месяц и наметить связанные с ним практики, которые вы будете выполнять регулярно в течение всего месяца (желательно каждый день). Длительность этого урока - 2 часа. Не прерывайтесь во время прохождения этого и следующих уроков данного практикума. Выбирайте такое время, когда вам ничто не помешает пройти урок на одном дыхании.</p><p></p><p>Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png\" alt=\"Месяц М+Ж\" width=\"504\" height=\"195\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я очень рад, что вы решились в течение месяца целенаправленно поработать с темой мужско-женских отношений. Сразу хочу обратить ваше внимание на то, что эта тема значительно шире ваших отношений с противоположным полом. Ведь мужское и женское окружает вас повсюду - и в мире природы, и в вашем внутреннем мире, и даже в языке, на котором мы говорим... Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые мы будем выполнять на совместных практиках, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу через Zoom тонко проконтролировать состояние каждого. А люди бывают разные. У каждого есть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие изменений<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь любовью... Так что поток уже поставлен. Входите в него и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для гармонизации мужско-женских отношений.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. Он поможет вам глубже разобраться в том, что такое любовь между мужчиной и женщиной, и что именно вы можете гармонизировать в течение этого месяца. Очень важно почувствовать её энергию, а также сформулировать лично для себя намерение на этот месяц и наметить связанные с ним практики, которые вы будете выполнять регулярно в течение всего месяца (желательно каждый день). Длительность этого урока - 2 часа. Не прерывайтесь во время прохождения этого и следующих уроков данного практикума. Выбирайте такое время, когда вам ничто не помешает пройти урок на одном дыхании.</p><p></p><p>Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-male-female-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png","alt":"Месяц М+Ж","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":232},{"id":"month-male-female-01-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я очень рад, что вы решились в течение месяца целенаправленно поработать с темой мужско-женских отношений. Сразу хочу обратить ваше внимание на то, что эта тема значительно шире ваших отношений с противоположным полом. Ведь мужское и женское окружает вас повсюду - и в мире природы, и в вашем внутреннем мире, и даже в языке, на котором мы говорим... Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые мы будем выполнять на совместных практиках, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу через Zoom тонко проконтролировать состояние каждого. А люди бывают разные. У каждого есть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие изменений<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь любовью... Так что поток уже поставлен. Входите в него и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для гармонизации мужско-женских отношений.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. Он поможет вам глубже разобраться в том, что такое любовь между мужчиной и женщиной, и что именно вы можете гармонизировать в течение этого месяца. Очень важно почувствовать её энергию, а также сформулировать лично для себя намерение на этот месяц и наметить связанные с ним практики, которые вы будете выполнять регулярно в течение всего месяца (желательно каждый день). Длительность этого урока - 2 часа. Не прерывайтесь во время прохождения этого и следующих уроков данного практикума. Выбирайте такое время, когда вам ничто не помешает пройти урок на одном дыхании.</p><p></p><p>Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-male-female-01','month-male-female',1,0,'Урок 1','[{"type":"video","vimeoId":"1105021182"},{"type":"text","markdown":"ЗАДАНИЕ:\nСформулируйте своё намерение на этот месяц практик, а также определите действия (практики), которые вы будете выполнять ежедневно, несмотря ни на какие непредвиденные затруднения."}]'::jsonb,'d5b816e9-ee23-5564-89d1-b402e0e42054') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('909eb9a6-bc27-595a-9d27-aabed619cb51','16094c0f-ae0c-585d-8bbd-6ce49bb2174c','Урок 2',2,0,'{М+Ж} Урок 2','{"ru":"{М+Ж} Урок 2"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png" alt="Месяц М+Ж" width="504" height="195" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы ко второму уроку. Он посвящён тому, чтобы видеть сценарность и красоту любовных отношений. При этом мы выполним комплекс асан с вниманием на свадхистхане, а также медитацию. Длительность урока 2.2 часа. Не прерывайтесь при его прохождении!</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png\" alt=\"Месяц М+Ж\" width=\"504\" height=\"195\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы ко второму уроку. Он посвящён тому, чтобы видеть сценарность и красоту любовных отношений. При этом мы выполним комплекс асан с вниманием на свадхистхане, а также медитацию. Длительность урока 2.2 часа. Не прерывайтесь при его прохождении!</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-male-female-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png","alt":"Месяц М+Ж","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":232},{"id":"month-male-female-02-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы ко второму уроку. Он посвящён тому, чтобы видеть сценарность и красоту любовных отношений. При этом мы выполним комплекс асан с вниманием на свадхистхане, а также медитацию. Длительность урока 2.2 часа. Не прерывайтесь при его прохождении!</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
