insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('8d75dfd5-52cd-52fe-8602-1e120a15fd96','16094c0f-ae0c-585d-8bbd-6ce49bb2174c','Урок 3',3,0,'{М+Ж} Урок 3','{"ru":"{М+Ж} Урок 3"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png" alt="Месяц М+Ж" width="504" height="195" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармонизации мужско-женских отношений. Он поможет вам глубже почувствовать любовь как симбиоз и возможность жить в большем комфорте. Эта тема, хотя и кажется простой, как куриное яйцо, в действительности ведёт очень глубоко - к пониманию мужской и женской природы. Чтобы выйти за рамки стереотипов вас ожидает тантрическая практика. Длительность урока - 2 часа.</p><p></p><p>Урок ожидает вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png\" alt=\"Месяц М+Ж\" width=\"504\" height=\"195\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармонизации мужско-женских отношений. Он поможет вам глубже почувствовать любовь как симбиоз и возможность жить в большем комфорте. Эта тема, хотя и кажется простой, как куриное яйцо, в действительности ведёт очень глубоко - к пониманию мужской и женской природы. Чтобы выйти за рамки стереотипов вас ожидает тантрическая практика. Длительность урока - 2 часа.</p><p></p><p>Урок ожидает вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-male-female-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png","alt":"Месяц М+Ж","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":232},{"id":"month-male-female-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармонизации мужско-женских отношений. Он поможет вам глубже почувствовать любовь как симбиоз и возможность жить в большем комфорте. Эта тема, хотя и кажется простой, как куриное яйцо, в действительности ведёт очень глубоко - к пониманию мужской и женской природы. Чтобы выйти за рамки стереотипов вас ожидает тантрическая практика. Длительность урока - 2 часа.</p><p></p><p>Урок ожидает вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
