insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('5918936c-e358-5282-8a06-909fe272dab3','16094c0f-ae0c-585d-8bbd-6ce49bb2174c','Урок 4',4,0,'{М+Ж} Урок 4','{"ru":"{М+Ж} Урок 4"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png" alt="Месяц М+Ж" width="504" height="195" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины практикума. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. </p><p></p><p>А сейчас пришло время четвертого урока. Этот урок посвящён осознаванию любовных отношений, как совместного развития. Внутренняя боль и неудовлетворённость, которые люди испытывают в отношениях, породили множество штампов и деструктивных форм поведения, прикрывающихся маской развития. Цель этого урока в том, чтобы, во-первых, честно посмотреть на происходящее, и отделить зёрна от плевел. А, во-вторых, в результате практики получить несомненный внутренний опыт (то есть мудрость, а не информационный шум) о том каким может быть ваше развитие в любовных отношениях. Причём, это не зависит от того, находитесь вы в отношениях сейчас или отношения формально завершены, хотя неформально продолжаются в виде внутренних диалогов и воспоминаний. Длительность урока - 1.3 часа.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png\" alt=\"Месяц М+Ж\" width=\"504\" height=\"195\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины практикума. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. </p><p></p><p>А сейчас пришло время четвертого урока. Этот урок посвящён осознаванию любовных отношений, как совместного развития. Внутренняя боль и неудовлетворённость, которые люди испытывают в отношениях, породили множество штампов и деструктивных форм поведения, прикрывающихся маской развития. Цель этого урока в том, чтобы, во-первых, честно посмотреть на происходящее, и отделить зёрна от плевел. А, во-вторых, в результате практики получить несомненный внутренний опыт (то есть мудрость, а не информационный шум) о том каким может быть ваше развитие в любовных отношениях. Причём, это не зависит от того, находитесь вы в отношениях сейчас или отношения формально завершены, хотя неформально продолжаются в виде внутренних диалогов и воспоминаний. Длительность урока - 1.3 часа.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-male-female-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png","alt":"Месяц М+Ж","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":232},{"id":"month-male-female-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины практикума. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. </p><p></p><p>А сейчас пришло время четвертого урока. Этот урок посвящён осознаванию любовных отношений, как совместного развития. Внутренняя боль и неудовлетворённость, которые люди испытывают в отношениях, породили множество штампов и деструктивных форм поведения, прикрывающихся маской развития. Цель этого урока в том, чтобы, во-первых, честно посмотреть на происходящее, и отделить зёрна от плевел. А, во-вторых, в результате практики получить несомненный внутренний опыт (то есть мудрость, а не информационный шум) о том каким может быть ваше развитие в любовных отношениях. Причём, это не зависит от того, находитесь вы в отношениях сейчас или отношения формально завершены, хотя неформально продолжаются в виде внутренних диалогов и воспоминаний. Длительность урока - 1.3 часа.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-male-female-04','month-male-female',4,7,'Урок 4','[{"type":"video","vimeoId":"1105021265"}]'::jsonb,'5918936c-e358-5282-8a06-909fe272dab3') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('3202b93b-a48d-5535-bcfc-73a5f59a676a','16094c0f-ae0c-585d-8bbd-6ce49bb2174c','Урок 5',5,0,'{М+Ж} Урок 5','{"ru":"{М+Ж} Урок 5"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png" alt="Месяц М+Ж" width="504" height="195" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока практикума, направленного на гармонизацию мужско-женских отношений. Он посвящён самому мистическому пониманию любви - как божьего дара. Любовь помогает нам почувствовать Бога, увидеть путь к нему, и пойти этим путём (путём любви). В общем-то, на уровне потока слов, это избитая тема. Нам же нужны не слова, а практика и результат. И тут наиболее уместна практика тантры. Она поможет вам ощутить и понять как любовь позволяет открыть Бога. А также эта практика глубоко вас гармонизирует. Длительность урока - 1 час 42 минуты.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>И, так как этот месячный практикум подходит к завершению, я хочу поблагодарить вас заинтерес и совместное выполнение практик. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я предлагаю вам выбрать и пройти практикум по другой тематике, которая сейчас трогает вас более всего. Со списком практикумов и курсов вы можее ознакомиться на мём сайте - <a href="https://zamkovoi.yoga/">https://zamkovoi.yoga/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png\" alt=\"Месяц М+Ж\" width=\"504\" height=\"195\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока практикума, направленного на гармонизацию мужско-женских отношений. Он посвящён самому мистическому пониманию любви - как божьего дара. Любовь помогает нам почувствовать Бога, увидеть путь к нему, и пойти этим путём (путём любви). В общем-то, на уровне потока слов, это избитая тема. Нам же нужны не слова, а практика и результат. И тут наиболее уместна практика тантры. Она поможет вам ощутить и понять как любовь позволяет открыть Бога. А также эта практика глубоко вас гармонизирует. Длительность урока - 1 час 42 минуты.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>И, так как этот месячный практикум подходит к завершению, я хочу поблагодарить вас заинтерес и совместное выполнение практик. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я предлагаю вам выбрать и пройти практикум по другой тематике, которая сейчас трогает вас более всего. Со списком практикумов и курсов вы можее ознакомиться на мём сайте - <a href=\"https://zamkovoi.yoga/\">https://zamkovoi.yoga/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-male-female-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png","alt":"Месяц М+Ж","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":232},{"id":"month-male-female-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока практикума, направленного на гармонизацию мужско-женских отношений. Он посвящён самому мистическому пониманию любви - как божьего дара. Любовь помогает нам почувствовать Бога, увидеть путь к нему, и пойти этим путём (путём любви). В общем-то, на уровне потока слов, это избитая тема. Нам же нужны не слова, а практика и результат. И тут наиболее уместна практика тантры. Она поможет вам ощутить и понять как любовь позволяет открыть Бога. А также эта практика глубоко вас гармонизирует. Длительность урока - 1 час 42 минуты.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>И, так как этот месячный практикум подходит к завершению, я хочу поблагодарить вас заинтерес и совместное выполнение практик. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я предлагаю вам выбрать и пройти практикум по другой тематике, которая сейчас трогает вас более всего. Со списком практикумов и курсов вы можее ознакомиться на мём сайте - <a href=\"https://zamkovoi.yoga/\">https://zamkovoi.yoga/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-male-female-05','month-male-female',5,7,'Урок 5','[{"type":"video","vimeoId":"1105021285"},{"type":"text","markdown":"Когда вы пройдёте этот урок, у вас может возникнуть вопрос - \"Что же дальше?\". И тут перед вами огромный выбор практикумов, интенсивов и курсов, которые я подготовил для гармонизации самых разных сфер жизни и внутренних психологических состояний. То есть сначала вам нужно определиться с направлением - что сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем понять сколько времени вы готовы посвятить погружению в эту тему. Ниже я перечислил другие практикумы и курсы, которые могут вас заинтересовать:\n\nПРАКТИКУМЫ:\n- Месяц здоровья: https://zamkovoi.yoga/m1 \n- Месяц наслаждений: https://zamkovoi.yoga/m2 \n- Месяц силы: https://zamkovoi.yoga/m3 \n- Месяц любви: https://zamkovoi.yoga/m4 \n- Месяц свободы: https://zamkovoi.yoga/m5 \n- Месяц мудрости: https://zamkovoi.yoga/m6 \n- Месяц святости: https://zamkovoi.yoga/m7\n\nКУРСЫ:\n- Йога и здоровье: https://zamkovoi.yoga/yoga1 \n- Йога и женственность: https://zamkovoi.yoga/yoga2 \n- Тантра - мистерия взаимоотношений: https://zamkovoi.yoga/tantra12 \n- Осуществи мечту: https://zamkovoi.yoga/yoga3 \n- Планета любви: https://zamkovoi.yoga/yoga4 \n- Источник творческой силы: https://zamkovoi.yoga/yoga5 \n- 36 шагов йоги: https://zamkovoi.yoga/yoga36 \n- Путь души: https://zamkovoi.yoga/yogas"}]'::jsonb,'3202b93b-a48d-5535-bcfc-73a5f59a676a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('649ec603-d55a-5e66-9334-800222f5f3c6','16094c0f-ae0c-585d-8bbd-6ce49bb2174c','Завершение практикума',6,0,'{М+Ж} Завершение практикума','{"ru":"{М+Ж} Завершение практикума"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png" alt="Месяц М+Ж" width="504" height="195" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию мужско-женских отношений. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность и гармонизировали проявление соответствующих энергий в своей жизни. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>Так как практикум закончился, предлагаю вам на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Я подготовил для вас серию практикумов, интенсивов и курсов. Чтобы выбрать, сначала вам нужно определиться с направлением - что сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем понять сколько времени вы готовы посвятить погружению в эту тему. Ниже я перечислил другие практикумы и курсы, которые могут вас заинтересовать:</p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href="https://zamkovoi.yoga/m1">https://zamkovoi.yoga/m1</a> <br>- Месяц наслаждений: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a> <br>- Месяц силы: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a> <br>- Месяц любви: <a href="https://zamkovoi.yoga/m4">https://zamkovoi.yoga/m4</a> <br>- Месяц свободы: <a href="https://zamkovoi.yoga/m5">https://zamkovoi.yoga/m5</a> <br>- Месяц мудрости: <a href="https://zamkovoi.yoga/m6">https://zamkovoi.yoga/m6</a> <br>- Месяц святости: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a> <br>- Йога и женственность: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a> <br>- Тантра - мистерия взаимоотношений: <a href="https://zamkovoi.yoga/tantra12">https://zamkovoi.yoga/tantra12</a> <br>- Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a> <br>- Планета любви: <a href="https://zamkovoi.yoga/yoga4">https://zamkovoi.yoga/yoga4</a> <br>- Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5">https://zamkovoi.yoga/yoga5</a> <br>- 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36">https://zamkovoi.yoga/yoga36</a> <br>- Путь души: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a> </p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png\" alt=\"Месяц М+Ж\" width=\"504\" height=\"195\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию мужско-женских отношений. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность и гармонизировали проявление соответствующих энергий в своей жизни. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>Так как практикум закончился, предлагаю вам на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Я подготовил для вас серию практикумов, интенсивов и курсов. Чтобы выбрать, сначала вам нужно определиться с направлением - что сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем понять сколько времени вы готовы посвятить погружению в эту тему. Ниже я перечислил другие практикумы и курсы, которые могут вас заинтересовать:</p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a> <br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> <br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a> <br>- Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a> <br>- Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a> <br>- Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a> <br>- Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a></p><p></p><p>КУРСЫ:<br>- Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a> <br>- Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a> <br>- Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a> <br>- Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a> <br>- Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a> <br>- Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a> <br>- 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a> <br>- Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> </p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-male-female-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-male-female/header-6f08a75983c0.png","alt":"Месяц М+Ж","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":232},{"id":"month-male-female-completion-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию мужско-женских отношений. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность и гармонизировали проявление соответствующих энергий в своей жизни. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>Так как практикум закончился, предлагаю вам на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>Я подготовил для вас серию практикумов, интенсивов и курсов. Чтобы выбрать, сначала вам нужно определиться с направлением - что сейчас вас более всего трогает (вызывает дискомфорт, или, наоборот, воодушевляет), а затем понять сколько времени вы готовы посвятить погружению в эту тему. Ниже я перечислил другие практикумы и курсы, которые могут вас заинтересовать:</p><p></p><p>ПРАКТИКУМЫ:<br>- Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a> <br>- Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> <br>- Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">htt